// WHO is asking, and about WHAT. Both come from the portal, which
// derived the username from a session it verified (HMAC over
// username|expiry, capped by the Dex token). Nothing here re-derives
// identity - and nothing here DECIDES ownership either. That decision
// happens below, against the cluster.
//
// THE EMPTY CASE IS LOAD-BEARING, exactly as in the project list: a
// blank username or a blank project must never be allowed to widen what
// gets looked up. Both are refused outright rather than defaulted.
const raw = $input.first().json || {};
const body = raw.body || raw;
const username = String(body.username || '').trim().toLowerCase();
const project  = String(body.project  || '').trim().toLowerCase();

// The same shapes used on the way in. A name that cannot be a namespace
// cannot name anything we would delete.
const userOk    = /^[a-z][a-z0-9._-]{2,31}$/.test(username);
const projectOk = /^[a-z][a-z0-9-]{1,28}[a-z0-9]$/.test(project)
                  && project.indexOf('--') === -1
                  && !/^(kube-|proj-|tenant-)/.test(project);

return [{ json: { username, project, usable: userOk && projectOk,
  namespace: 'tenant-' + project } }];

// THE OWNERSHIP CHECK. This is the whole reason the portal does not
// decide: the portal knows a project name because a page rendered it,
// which proves nothing about who owns it NOW. The answer here comes from
// the namespace's own labels, read back from the API server.
//
// IT FAILS CLOSED, the same way `Is it ours to use?` does in the
// provisioning workflow (Problem #147): unreadable, missing, or
// unlabelled is NOT ours. Only an explicit owner match proceeds.
const who = $('Who and what?').first().json;
let labels = null, readable = false;
try {
  const j = $('Read the namespace').first().json;
  if (j && j.kind === 'Namespace' && j.metadata) {
    readable = true;
    labels = j.metadata.labels || {};
  }
} catch (e) { readable = false; labels = null; }

// `tenant` is read as well as `owner` so namespaces created before
// 2026-09-08 do not lock their owners out of deleting them.
const owner = labels ? (labels.owner || labels.tenant || '') : '';
const owned = readable && !!owner && owner === who.username;

return [{ json: { username: who.username, project: who.project,
  namespace: who.namespace, readable, owned } }];

// REPORT WHAT THE API SERVER CONFIRMED, never what was attempted.
//
// A namespace DELETE returns 200 with the object in state Terminating -
// the removal is asynchronous and can take many seconds while finalizers
// run. 200 therefore means ACCEPTED, and that is what is claimed: the
// project will disappear. Claiming "gone" at this instant would be a
// state nothing has measured yet.
const who = $('Who and what?').first().json;

function code(nodeName) {
  try {
    const r = $(nodeName).first().json;
    return r.statusCode || (r.body && r.body.code) || 0;
  } catch (e) { return 0; }
}

const nsCode = code('Delete the namespace');
const jobCode = code('Purge the Nomad job');

let nomadNs = 'unknown';
try {
  const r = $('Drop the Nomad namespace').first().json;
  nomadNs = r.nomadNamespace || 'unknown';
} catch (e) { nomadNs = 'unknown'; }

// THE KUBERNETES NAMESPACE IS THE PROMISE. It is what the project list
// is built from, so its removal is what makes the project disappear.
const nsGone = nsCode === 200 || nsCode === 202 || nsCode === 404;
const refused = nsCode === 403;

// Nomad is reported separately and does NOT gate success. A Kubernetes
// tenant has no Nomad job or namespace at all, so 404 there is normal.
const jobOk = jobCode === 200 || jobCode === 404;
const nomadOk = nomadNs === 'removed' || nomadNs === 'absent';

let deleted = nsGone && !refused;
let message;
if (deleted && nomadOk) {
  message = 'Le projet ' + who.project + ' a ete supprime. Son espace et tout '
          + 'ce qu il contenait ont ete effaces.';
} else if (deleted && !nomadOk) {
  // Honest about the half that did not complete. The project vanishes
  // from the list either way, but the NAME may stay unavailable until the
  // Nomad namespace is cleared by hand - so say so rather than let the
  // user discover it when they try to reuse it.
  message = 'Le projet ' + who.project + ' a ete supprime, mais une partie de '
          + 'son espace n a pas pu etre effacee. Ce nom pourrait rester '
          + 'indisponible ; contactez un administrateur si vous voulez le '
          + 'reutiliser.';
} else if (refused) {
  message = 'La suppression a ete refusee par le cluster. Rien ne peut etre '
          + 'garanti comme supprime.';
} else {
  message = 'La suppression n a pas pu etre confirmee. Rien n a ete supprime '
          + 'avec certitude.';
}

return [{ json: { owned: true, deleted, project: who.project,
  namespaceStatus: nsCode, nomadJobStatus: jobCode, nomadNamespace: nomadNs,
  nomadFullyCleared: nomadOk && jobOk, message } }];

// NOT THEIRS, or not readable. Nothing has been called at this point -
// the refusal happens BEFORE any delete, not after one is undone.
//
// The wording is deliberately identical to a project that does not
// exist. Telling one user that another user's project is real would be
// a disclosure in itself.
const who = $('Who and what?').first().json;
return [{ json: { owned: false, deleted: false, project: who.project,
  message: 'Ce projet est introuvable dans votre espace. Rien n a ete supprime.' } }];

// Hand the namespace manager what it needs, and nothing else.
//
// The Nomad MANAGEMENT token is not here and must never be: namespace
// deletion cannot be expressed as a scoped policy (Problem #138), so the
// credential lives in one two-operation workflow that this reaches by ID.
// That bounds accidental blast radius, not an attacker with n8n editor
// access - say it that way and no stronger.
const who = $('Who and what?').first().json;
return [{ json: { action: 'delete', name: who.namespace } }];
